// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// GetBlockByHash Block header by hash
	// (GET /node/blocks/hash/{blockHash})
	GetBlockByHash(ctx context.Context, request GetBlockByHashRequestObject) (GetBlockByHashResponseObject, error)
	// GetBlockByHeight Block header at a height
	// (GET /node/blocks/height/{height})
	GetBlockByHeight(ctx context.Context, request GetBlockByHeightRequestObject) (GetBlockByHeightResponseObject, error)
	// GetLatestBlock Header of the chain tip
	// (GET /node/blocks/latest)
	GetLatestBlock(ctx context.Context, request GetLatestBlockRequestObject) (GetLatestBlockResponseObject, error)
	// GetFeeEstimate Current fee estimate
	// (GET /node/fee-estimate)
	GetFeeEstimate(ctx context.Context, request GetFeeEstimateRequestObject) (GetFeeEstimateResponseObject, error)
	// GetNodeInfo Node status and sync progress
	// (GET /node/info)
	GetNodeInfo(ctx context.Context, request GetNodeInfoRequestObject) (GetNodeInfoResponseObject, error)
	// GetMempoolStats Transaction pool statistics
	// (GET /node/mempool)
	GetMempoolStats(ctx context.Context, request GetMempoolStatsRequestObject) (GetMempoolStatsResponseObject, error)
	// GenerateBlocks Mine blocks (regtest only)
	// (POST /node/regtest/generate-blocks)
	GenerateBlocks(ctx context.Context, request GenerateBlocksRequestObject) (GenerateBlocksResponseObject, error)
	// GetTransaction Look up a transaction by hash
	// (GET /node/transactions/{txHash})
	GetTransaction(ctx context.Context, request GetTransactionRequestObject) (GetTransactionResponseObject, error)
	// ListWallets List wallets
	// (GET /wallets)
	ListWallets(ctx context.Context, request ListWalletsRequestObject) (ListWalletsResponseObject, error)
	// CreateWallet Create a wallet
	// (POST /wallets)
	CreateWallet(ctx context.Context, request CreateWalletRequestObject) (CreateWalletResponseObject, error)
	// RestoreWalletFromKeys Restore a wallet from its keys
	// (POST /wallets/restore/keys)
	RestoreWalletFromKeys(ctx context.Context, request RestoreWalletFromKeysRequestObject) (RestoreWalletFromKeysResponseObject, error)
	// RestoreWalletFromSeed Restore a wallet from its mnemonic seed
	// (POST /wallets/restore/seed)
	RestoreWalletFromSeed(ctx context.Context, request RestoreWalletFromSeedRequestObject) (RestoreWalletFromSeedResponseObject, error)
	// ListWalletAddresses Addresses of one account
	// (GET /wallets/{walletName}/addresses)
	ListWalletAddresses(ctx context.Context, request ListWalletAddressesRequestObject) (ListWalletAddressesResponseObject, error)
	// CreateWalletAddress Create a subaddress
	// (POST /wallets/{walletName}/addresses)
	CreateWalletAddress(ctx context.Context, request CreateWalletAddressRequestObject) (CreateWalletAddressResponseObject, error)
	// GetWalletBalance Balance of one account
	// (GET /wallets/{walletName}/balance)
	GetWalletBalance(ctx context.Context, request GetWalletBalanceRequestObject) (GetWalletBalanceResponseObject, error)
	// CloseWallet Save and close a wallet
	// (POST /wallets/{walletName}/close)
	CloseWallet(ctx context.Context, request CloseWalletRequestObject) (CloseWalletResponseObject, error)
	// OpenWallet Open a wallet
	// (POST /wallets/{walletName}/open)
	OpenWallet(ctx context.Context, request OpenWalletRequestObject) (OpenWalletResponseObject, error)
	// GetWalletStatus Wallet status and sync progress
	// (GET /wallets/{walletName}/status)
	GetWalletStatus(ctx context.Context, request GetWalletStatusRequestObject) (GetWalletStatusResponseObject, error)
	// ListWalletTransfers Transfer history
	// (GET /wallets/{walletName}/transfers)
	ListWalletTransfers(ctx context.Context, request ListWalletTransfersRequestObject) (ListWalletTransfersResponseObject, error)
	// SendTransfer Send XMR
	// (POST /wallets/{walletName}/transfers)
	SendTransfer(ctx context.Context, request SendTransferRequestObject) (SendTransferResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

